const root='/workspace/REP-WARS-2-COMPLETION-AUDIT';const r=p=>require(root+'/dist/'+p);const fs=require('fs');
const {createGameState}=r('state/createGameState');const {cloneGameState}=r('state/cloneGameState');const {snapshotGameState}=r('persistence/snapshot');const {hydratePersistedPayload}=r('persistence/hydrate');const {runEventEngineTurn}=r('world/eventTick');const {WorldSimulator}=r('events/WorldSimulator');const {Orchestrator}=r('orchestration/orchestrator');const {checkGameStateInvariants}=r('state/gameStateInvariants');
const {loadProductionLevel2Definition}=r('worldDefinition');const {progressArmyMovements}=r('army/movement');const {isCommandExposed}=r('server/allowlist');const {getCommandDefinition}=r('orchestration/commandIndex');const {serializePublicGameState}=r('orchestration/publicView');
const out={};
const def=loadProductionLevel2Definition();if(!def.ok)throw Error('level2 load');const base=createGameState({world:def.definition,seed:11});
let s=cloneGameState(base),found=null;
for(let i=0;i<100&&!found;i++){
 const prev=Object.fromEntries([...s.territories].map(([id,t])=>[id,{...t.resourceOutput}]));const step=runEventEngineTurn(s,new WorldSimulator());
 const changed=[...s.territories].filter(([id,t])=>JSON.stringify(t.resourceOutput)!==JSON.stringify(prev[id]));
 if(changed.length){const after=hydratePersistedPayload(snapshotGameState(s));found={turn:s.turn,triggered:step.events.filter(e=>e.kind==='imperial').map(e=>e.title),changes:changed.map(([id,t])=>({id,before:prev[id],eventResult:t.resourceOutput,afterReload:after.territories.get(id).resourceOutput})),invariantProblems:checkGameStateInvariants(s).map(x=>x.code)};}
}
out.eventOutputReload=found;
const p=base.playerFactionId;const a=[...base.armies.values()].find(a=>a.owner===p);const origin=base.territories.get(a.location);const dest=origin.neighboring.find(id=>base.territories.get(id).owner!==p);
if(dest){const o=new Orchestrator(cloneGameState(base));const moved=o.execute({commandId:'MOVE',playerId:'audit',parameters:{armyId:a.id,destinationTerritoryId:dest}});const state=o.getState();const m=state.armies.get(a.id).movement;if(m){state.worldTick=m.startedAtTick+m.durationTicks;state.accruedTargetWorldTick=state.worldTick;const arrived=progressArmyMovements(state,state.worldTick);out.hostileMove={success:moved.success,from:origin.id,to:dest,destinationOwner:state.territories.get(dest).owner,armyOwner:p,arrival:arrived,activeInvasions:state.activeInvasions.size,attackIntent:state.armies.get(a.id).attackIntent??null,invariantProblems:checkGameStateInvariants(state).map(x=>x.code)};}
 const n=cloneGameState(base);const former=n.territories.get(dest).owner;n.territories.get(dest).owner=null;for(const f of n.factions.values())f.territories=f.territories.filter(id=>id!==dest);const no=new Orchestrator(n);const res=no.execute({commandId:'ATTACK',playerId:'audit',parameters:{territoryId:dest}});out.neutralAttack={validBefore:checkGameStateInvariants(n).map(x=>x.code),success:res.success,errors:res.errors,formerOwner:former};}
out.commandAvailability=Object.fromEntries(['DEPLOY_TROOPS','RESTART_WORLD','REINFORCE','RETREAT','RESOLVE_EVENT_CHOICE','EXPAND'].map(id=>[id,{registered:!!getCommandDefinition(id),exposed:isCommandExposed(id)}]));
(async()=>{const {createInMemoryPersistence}=r('server/persistencePort');const {InMemoryGameStateStore}=r('persistence/inMemoryGameStateStore');const {createSessionHost}=r('server/session');const {createCommandHttpServer}=r('server/http');
 const store=new InMemoryGameStateStore(),s=createGameState();s.playerRewards.bankedTroops=100;const saved=store.save('audit-player',s,0);if(!saved.ok)throw Error(saved.message);const host=createSessionHost(createInMemoryPersistence(store),{nowMs:()=>0});const server=createCommandHttpServer(host,{identity:{mode:'authenticated',authenticate:()=> 'audit-player'}});await new Promise(ok=>server.listen(0,'127.0.0.1',ok));
 const post=async(path,body)=>{const r=await fetch(`http://127.0.0.1:${server.address().port}${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,body:await r.json()};};
 try{const req={commandId:'DEPLOY_TROOPS',requestId:'same-logical-request',parameters:{territoryId:s.levelAnchorTerritoryIds[0],quantity:10}};const x=await post('/commands',req),y=await post('/commands',req);const l=store.load('audit-player');out.httpUnsequencedRetry={first:{http:x.status,success:x.body.success,payload:x.body.payload},second:{http:y.status,success:y.body.success,payload:y.body.payload},bankAfter:l.state.playerRewards.bankedTroops};
 const open=await post('/session/open',{requestId:'open-audit'});out.sessionOpenShape=open;const session=open.body.session??open.body;const sel=await post('/commands',{commandId:'GET_WORKOUT_SELECTION',parameters:{purpose:'NORMAL_TROOPS',size:'STANDARD'}});out.productionWorkoutSelection=sel;
 const start=await post('/commands',{commandId:'START_WORKOUT',requestId:'normal-start',gameplaySessionId:session.sessionId,commandSequence:1,renewalSequence:1,parameters:{purpose:'NORMAL_TROOPS',size:'STANDARD'}});out.productionWorkoutStart=start;
 }finally{await new Promise(ok=>server.close(ok));}
 fs.writeFileSync('/tmp/backend-completion-audit/probes.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));})().catch(e=>{console.error(e);process.exitCode=1;});

