const root='/workspace/REP-WARS-2-COMPLETION-AUDIT';const r=p=>require(root+'/dist/'+p);const fs=require('fs');
const {createGameState}=r('state/createGameState');const {Orchestrator}=r('orchestration/orchestrator');const {snapshotGameState}=r('persistence/snapshot');const {hydratePersistedPayload}=r('persistence/hydrate');const {checkGameStateInvariants}=r('state/gameStateInvariants');const {runEventEngineTurn}=r('world/eventTick');const {WorldSimulator}=r('events/WorldSimulator');const {loadProductionLevel2Definition,getDefaultWorldCatalog}=r('worldDefinition');const {serializeLevel1TutorialView,syncLevel1Tutorial,assertLevel1TutorialWorkoutAllowed}=r('gameplay/tutorial/level1');
const out={};
const s=createGameState();s.playerRewards.bankedTroops=500;s.level1Tutorial.firstWorkoutSessionId='audit-already-settled-session';syncLevel1Tutorial(s);const before=serializeLevel1TutorialView(s);const o=new Orchestrator(s);const dep=o.execute({commandId:'DEPLOY_TROOPS',playerId:'audit',parameters:{territoryId:s.levelAnchorTerritoryIds[0],quantity:500}});const attack=o.execute({commandId:'ATTACK',playerId:'audit',parameters:{territoryId:before.firstAttackTerritoryIds[0],armyId:dep.payload.armyId}});const bankAttack=o.execute({commandId:'ATTACK',playerId:'audit',parameters:{territoryId:before.firstAttackTerritoryIds[0],commitAmount:500}});let workout;try{assertLevel1TutorialWorkoutAllowed(o.getState(),'NORMAL_TROOPS');workout='allowed';}catch(e){workout={code:e.code,message:e.message};}
const restart=o.execute({commandId:'RESTART_WORLD',playerId:'audit',parameters:{}});out.tutorialDeployment={fixture:'Registered Level1, already-settled first-workout tutorial beat and bank500; no production policy invented',before,deploy:{success:dep.success,payload:dep.payload},armyAttack:{success:attack.success,errors:attack.errors},bankAttack:{success:bankAttack.success,errors:bankAttack.errors},normalWorkoutGuard:workout,restart:{success:restart.success,errors:restart.errors},after:serializeLevel1TutorialView(o.getState()),bank:o.getState().playerRewards.bankedTroops,invariants:checkGameStateInvariants(o.getState())};
const def=JSON.parse(JSON.stringify(loadProductionLevel2Definition().definition));const e=createGameState({world:def,seed:11});for(const t of e.territories.values())t.population=3000;let found=null;
for(let i=0;i<100&&!found;i++){const prev=Object.fromEntries([...e.territories].map(([id,t])=>[id,{...t.resourceOutput}]));const result=runEventEngineTurn(e,new WorldSimulator());const changed=[...e.territories].filter(([id,t])=>JSON.stringify(t.resourceOutput)!==JSON.stringify(prev[id]));if(changed.length){const reload=hydratePersistedPayload(snapshotGameState(e));found={turn:e.turn,eventSummary:result.summary,changes:changed.map(([id,t])=>({id,before:prev[id],eventResult:t.resourceOutput,reloaded:reload.territories.get(id).resourceOutput})),invariants:checkGameStateInvariants(e),reloadInvariants:checkGameStateInvariants(reload)};}}
out.eventHydration={fixture:'RegisteredLevel2 with runtimepopulation3000 each territory, seed11; population is an explicit non-production fixture assumption to reach event engine; authored output unchanged',result:found};fs.writeFileSync('/tmp/backend-completion-audit/cross-system-probes.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));

