const root='/workspace/REP-WARS-2-COMPLETION-AUDIT',r=p=>require(root+'/dist/'+p),fs=require('fs');
const {createGameState}=r('state/createGameState'),{loadProductionLevel2Definition}=r('worldDefinition'),{Orchestrator}=r('orchestration/orchestrator'),{runEventEngineTurn}=r('world/eventTick'),{WorldSimulator}=r('events/WorldSimulator'),{checkGameStateInvariants}=r('state/gameStateInvariants');
const make=()=>createGameState({world:loadProductionLevel2Definition().definition,seed:11});const e=make();let triggered=0;for(let i=0;i<100;i++)triggered+=runEventEngineTurn(e,new WorldSimulator()).triggered;
const s=make(),o=new Orchestrator(s);const army=[...s.armies.values()].find(a=>a.owner===s.playerFactionId),dest=s.territories.get(army.location).neighboring.find(id=>s.territories.get(id).owner!==army.owner);const moved=o.execute({commandId:'MOVE',playerId:'audit',parameters:{armyId:army.id,destinationTerritoryId:dest}});const duration=o.getState().armies.get(army.id).movement.durationTicks;const advance=o.execute({commandId:'ADVANCE_WORLD',playerId:'system',parameters:{elapsedTicks:duration}});const after=o.getState();const out={naturalEvents:{world:'Level 2',seed:11,turns:100,triggered,populations:[...e.territories.values()].map(t=>t.population),invariants:checkGameStateInvariants(e)},hostileArrival:{world:'Level 2',seed:11,moveSuccess:moved.success,advanceSuccess:advance.success,ticks:duration,armyLocation:after.armies.get(army.id)?.location,targetOwner:after.territories.get(dest).owner,player:after.playerFactionId,attackIntent:after.armies.get(army.id)?.attackIntent,activeInvasions:after.activeInvasions.size,battleResults:advance.payload.worldAdvance?.commitmentResolutions,errors:advance.errors,invariants:checkGameStateInvariants(after)}};fs.writeFileSync('/tmp/backend-completion-audit/arrival-events.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));
